from collections import Counter

def transform(grid):
    if not grid or not grid[0]:
        return grid

    height = len(grid)
    width = len(grid[0])

    # Count to find background (most frequent)
    counts = Counter()
    for row in grid:
        counts.update(row)
    background = max(counts.keys(), key=lambda x: counts[x])

    # Initialize result with background
    result = [[background] * width for _ in range(height)]

    # Row 0 = input row 0
    for c in range(width):
        result[0][c] = grid[0][c]

    # Even rows = row 0
    for r in range(2, height, 2):
        for c in range(width):
            result[r][c] = result[0][c]

    # Odd rows: for each non-background value in row 0, spread to left/right neighbors
    for r in range(1, height, 2):
        for c in range(width):
            val = grid[0][c]
            if val != background:
                if c - 1 >= 0:
                    result[r][c - 1] = val
                if c + 1 < width:
                    result[r][c + 1] = val

